"use strict";(globalThis.webpackChunkbvk_arbeitgeberportal_doku=globalThis.webpackChunkbvk_arbeitgeberportal_doku||[]).push([[8323],{8037:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"neue-funktion-im-arbeitgeberportal","metadata":{"permalink":"/bvk_arbeitgeberportal_doku/aktuelles/neue-funktion-im-arbeitgeberportal","source":"@site/blog/2026-04-13-neue-funktion-im-arbeitgeberportal.md","title":"Neue Funktion im Arbeitgeberportal","description":"Im Arbeitgeberportal steht eine neue Funktion zur Verf\xfcgung.","date":"2026-04-13T00:00:00.000Z","tags":[{"inline":true,"label":"Portal","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/tags/portal"},{"inline":true,"label":"Update","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/tags/update"}],"readingTime":0.25,"hasTruncateMarker":false,"authors":[{"name":"BVK Redaktion","title":"BVK Arbeitgeberportal","url":"https://www.bvk.ch","imageURL":"https://www.bvk.ch/favicon.ico","key":"bvk-redaktion","page":null}],"frontMatter":{"slug":"neue-funktion-im-arbeitgeberportal","title":"Neue Funktion im Arbeitgeberportal","authors":["bvk-redaktion"],"tags":["Portal","Update"]},"unlisted":false,"nextItem":{"title":"Zweite S\xe4ule - Was Arbeitgeber im Alltag besonders im Blick behalten sollten","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/zweite-saeule-was-arbeitgeber-wissen-sollten"}},"content":"Im Arbeitgeberportal steht eine neue Funktion zur Verf\xfcgung.\\n\\n## Was ist neu?\\n\\nDie neue Funktion verbessert den Zugriff auf wichtige Informationen und vereinfacht ausgew\xe4hlte Arbeitsabl\xe4ufe im Portal.\\n\\n## Was bedeutet das f\xfcr Arbeitgeber?\\n\\n- Schnellere Navigation\\n- Bessere \xdcbersicht\\n- Einfachere Nutzung im Alltag\\n\\n## Weitere Informationen\\n\\nEine ausf\xfchrliche Beschreibung finden Sie im [Benutzerhandbuch](/docs/benutzerhandbuch)."},{"id":"zweite-saeule-was-arbeitgeber-wissen-sollten","metadata":{"permalink":"/bvk_arbeitgeberportal_doku/aktuelles/zweite-saeule-was-arbeitgeber-wissen-sollten","source":"@site/blog/2026-04-13-zweite-saeule-was-arbeitgeber-wissen-sollten.md","title":"Zweite S\xe4ule - Was Arbeitgeber im Alltag besonders im Blick behalten sollten","description":"Die berufliche Vorsorge begleitet Arbeitgeber durch den ganzen Lebenszyklus eines Arbeitsverh\xe4ltnisses: vom Eintritt \xfcber Lohn\xe4nderungen bis zum Austritt. Gerade im Alltag zeigt sich, dass viele Themen nicht kompliziert sind \u2013 aber saubere Prozesse und ein gutes Verst\xe4ndnis sehr wichtig sind.","date":"2026-04-13T00:00:00.000Z","tags":[{"inline":true,"label":"Arbeitgeber","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/tags/arbeitgeber"},{"inline":true,"label":"Zweite S\xe4ule","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/tags/zweite-saule"},{"inline":true,"label":"Vorsorgewissen","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/tags/vorsorgewissen"}],"readingTime":2.05,"hasTruncateMarker":false,"authors":[{"name":"BVK Redaktion","title":"BVK Arbeitgeberportal","url":"https://www.bvk.ch","imageURL":"https://www.bvk.ch/favicon.ico","key":"bvk-redaktion","page":null}],"frontMatter":{"slug":"zweite-saeule-was-arbeitgeber-wissen-sollten","title":"Zweite S\xe4ule - Was Arbeitgeber im Alltag besonders im Blick behalten sollten","authors":["bvk-redaktion"],"tags":["Arbeitgeber","Zweite S\xe4ule","Vorsorgewissen"]},"unlisted":false,"prevItem":{"title":"Neue Funktion im Arbeitgeberportal","permalink":"/bvk_arbeitgeberportal_doku/aktuelles/neue-funktion-im-arbeitgeberportal"}},"content":"Die berufliche Vorsorge begleitet Arbeitgeber durch den ganzen Lebenszyklus eines Arbeitsverh\xe4ltnisses: vom Eintritt \xfcber Lohn\xe4nderungen bis zum Austritt. Gerade im Alltag zeigt sich, dass viele Themen nicht kompliziert sind \u2013 aber saubere Prozesse und ein gutes Verst\xe4ndnis sehr wichtig sind.\\n\\n## Warum die zweite S\xe4ule f\xfcr Arbeitgeber relevant ist\\n\\nDie zweite S\xe4ule ist ein zentraler Bestandteil der sozialen Absicherung in der Schweiz. F\xfcr Arbeitgeber bedeutet das vor allem: Ver\xe4nderungen im Arbeitsverh\xe4ltnis wirken sich oft auch auf die berufliche Vorsorge aus.\\n\\nTypische Beispiele sind:\\n\\n- Eintritte neuer Mitarbeitender\\n- Austritte\\n- Lohn\xe4nderungen\\n- \xc4nderungen des Besch\xe4ftigungsgrads\\n- unbezahlter Urlaub\\n- l\xe4ngere Abwesenheiten\\n- Pensionierungen\\n\\nJe sauberer solche Ereignisse intern erfasst und weiterverarbeitet werden, desto einfacher wird die Zusammenarbeit mit der Pensionskasse.\\n\\n## Wo im Alltag h\xe4ufig Unsicherheiten entstehen\\n\\nIn der Praxis sind es oft nicht die grossen Spezialf\xe4lle, sondern die allt\xe4glichen Themen, bei denen Fragen entstehen.\\n\\n### Eintritt von Mitarbeitenden\\nBeim Eintritt neuer Mitarbeitender ist wichtig, dass die relevanten Daten vollst\xe4ndig und rechtzeitig vorliegen. Dazu geh\xf6ren insbesondere Angaben, die f\xfcr die korrekte versicherungstechnische Erfassung notwendig sind.\\n\\n### Lohn\xe4nderungen\\n\xc4nderungen beim Lohn k\xf6nnen Einfluss auf die Vorsorgesituation haben. Deshalb ist es wichtig, dass solche Anpassungen nachvollziehbar und termingerecht verarbeitet werden.\\n\\n### \xc4nderungen des Besch\xe4ftigungsgrads\\nAuch eine Anpassung des Pensums kann Auswirkungen auf die versicherte Situation haben. Solche \xc4nderungen sollten deshalb nicht nur arbeitsvertraglich, sondern auch administrativ sauber begleitet werden.\\n\\n### Austritt\\nBeim Austritt ist entscheidend, dass der Fall korrekt abgeschlossen wird und die n\xf6tigen Informationen vollst\xe4ndig vorliegen. Ein sauberer Prozess hilft, R\xfcckfragen und Verz\xf6gerungen zu vermeiden.\\n\\n## Gute Praxis f\xfcr Arbeitgeber\\n\\nIm Alltag bew\xe4hren sich vor allem klare Zust\xe4ndigkeiten und einheitliche Abl\xe4ufe.\\n\\nHilfreich sind insbesondere:\\n\\n- klare interne Verantwortlichkeiten\\n- standardisierte Prozesse f\xfcr Eintritte, \xc4nderungen und Austritte\\n- fr\xfchzeitige Erfassung relevanter \xc4nderungen\\n- regelm\xe4ssige Pr\xfcfung von Meldungen und Stammdaten\\n- gute Abstimmung zwischen HR, Lohnadministration und verantwortlichen Fachpersonen\\n\\n## Warum digitale Prozesse helfen\\n\\nEin Arbeitgeberportal kann helfen, Informationen strukturiert zu erfassen und Arbeitsabl\xe4ufe transparenter zu machen. Das reduziert den manuellen Aufwand und erleichtert die Nachvollziehbarkeit.\\n\\nBesonders hilfreich sind dabei:\\n\\n- klar gef\xfchrte Formulare\\n- strukturierte Upload- und Download-Prozesse\\n- definierte Rollen und Berechtigungen\\n- ein zentraler Zugang zu wichtigen Informationen\\n\\n## Fazit\\n\\nF\xfcr Arbeitgeber ist die zweite S\xe4ule kein isoliertes Fachthema, sondern Teil des administrativen Alltags. Wer Eintritte, \xc4nderungen und Austritte mit klaren Prozessen bearbeitet, schafft eine gute Grundlage f\xfcr eine verl\xe4ssliche und effiziente Zusammenarbeit.\\n\\nWenn Sie das Arbeitgeberportal nutzen, lohnt es sich, interne Abl\xe4ufe regelm\xe4ssig zu \xfcberpr\xfcfen und Verantwortlichkeiten klar festzulegen. Das erleichtert nicht nur die t\xe4gliche Arbeit, sondern unterst\xfctzt auch eine konsistente Datenqualit\xe4t.\\n\\n## Weiterf\xfchrende Informationen\\n\\n- [Benutzerhandbuch](/docs/benutzerhandbuch)\\n- [Adminhandbuch](/docs/adminhandbuch)\\n- [FAQ](/docs/faq)"}]}}')}}]);